// ---------- Utilidades de formato (estilo Power BI: "1,40 Mi", "3,49 Mil") ----------
const dec = (n, d) => n.toLocaleString('pt-BR', { minimumFractionDigits: d, maximumFractionDigits: d });
function fmtPBI(v) {
  const n = Number(v) || 0, a = Math.abs(n);
  if (a >= 1e6) return `${dec(n / 1e6, 2)} Mi`;
  if (a >= 1e3) return `${dec(n / 1e3, 2)} Mil`;
  return dec(n, 2);
}
function fmtLabel(v) {
  const n = Number(v) || 0, a = Math.abs(n);
  if (a >= 1e6) return `${dec(n / 1e6, 2)} Mi`;
  if (a >= 1e3) return `${dec(n / 1e3, 1)} Mil`;
  return dec(n, 0);
}
function fmtAxis(v) {
  const a = Math.abs(v);
  if (a >= 1e6) return `${dec(v / 1e6, 1)} Mi`;
  if (a >= 1e3) return `${dec(v / 1e3, 0)} Mil`;
  return dec(v, 0);
}
const fmtBRL = v => v.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
const fmtNum = v => v.toLocaleString('pt-BR');
const esc = s => String(s).replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const MESES = ['janeiro','fevereiro','março','abril','maio','junho','julho','agosto','setembro','outubro','novembro','dezembro'];
const nomeMes = m => MESES[Number(m.slice(5, 7)) - 1] || m;
const AMBER = '#fdb515', GRID = '#4d4d4d', TXT = '#e6e6e6', MUTED = '#bdbdbd';

const uniqueSorted = a => [...new Set(a)].sort((x, y) => x.localeCompare(y, 'pt-BR'));
const regioes = uniqueSorted(VENDAS.map(r => r.regiao));
const categorias = uniqueSorted(VENDAS.map(r => r.categoria));
const meses = uniqueSorted(VENDAS.map(r => r.mes));

// ---------- Filtros (seleção múltipla; nenhum marcado = tudo, como no Power BI) ----------
function buildChecks(id, options, label, chip) {
  const box = document.getElementById(id);
  box.innerHTML = options.map(o =>
    `<label class="${chip ? '' : 'opt'}"><input type="checkbox" data-grupo="${id}" value="${esc(o)}"><span>${esc(label ? label(o) : o)}</span></label>`
  ).join('');
  if (!chip) box.querySelectorAll('span').forEach(s => s.style.display = 'inline');
}
buildChecks('fRegiao', regioes);
buildChecks('fCategoria', categorias);
buildChecks('fMes', meses, m => nomeMes(m).slice(0, 3), true);
const selecionados = id => new Set([...document.querySelectorAll(`input[data-grupo="${id}"]:checked`)].map(i => i.value));
function toggleFiltro(id, valor) {
  const el = [...document.querySelectorAll(`input[data-grupo="${id}"]`)].find(i => i.value === valor);
  if (el) { el.checked = !el.checked; render(); }
}

// ---------- Gráficos ----------
const setChart = (id, html) => { document.getElementById(id).innerHTML = html; };
const empty = () => `<div class="empty-chart">Sem dados para os filtros selecionados.</div>`;
const svg = (w, h, body, label) => `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(label)}" xmlns="http://www.w3.org/2000/svg">${body}</svg>`;
function niceMax(v) {
  if (!v || v <= 0) return 1;
  const p = Math.pow(10, Math.floor(Math.log10(v))), n = v / p;
  return (n <= 1 ? 1 : n <= 2 ? 2 : n <= 2.5 ? 2.5 : n <= 5 ? 5 : 10) * p;
}

function renderCategoria(entries, ativos) {
  if (!entries.length) return setChart('chartCategoria', empty());
  const w = 520, h = 280, p = { l: 96, r: 70, t: 14, b: 14 };
  const cw = w - p.l - p.r, rowH = (h - p.t - p.b) / entries.length, max = Math.max(...entries.map(e => e[1])) || 1;
  let b = '';
  entries.forEach(([nome, val], i) => {
    const bh = Math.min(rowH * 0.5, 34), y = p.t + i * rowH + (rowH - bh) / 2, bw = Math.max(2, (val / max) * cw);
    const dim = ativos.size && !ativos.has(nome) ? 0.35 : 1;
    b += `<text x="${p.l - 8}" y="${y + bh * 0.7}" text-anchor="end" fill="${TXT}" font-size="12">${esc(nome)}</text>`;
    b += `<rect class="hit" data-filtro="fCategoria" data-valor="${esc(nome)}" x="${p.l}" y="${y}" width="${bw}" height="${bh}" fill="${AMBER}" opacity="${dim}"><title>${esc(nome)}: ${esc(fmtBRL(val))}</title></rect>`;
    b += `<text x="${p.l + bw + 6}" y="${y + bh * 0.7}" fill="#fff" font-size="12" font-weight="600">${fmtLabel(val)}</text>`;
  });
  setChart('chartCategoria', svg(w, h, b, 'Faturamento por categoria'));
}

function renderMensal(labels, values, ativos) {
  if (!values.length || values.every(v => !v)) return setChart('chartMensal', empty());
  const w = 560, h = 280, p = { l: 58, r: 34, t: 30, b: 32 }, cw = w - p.l - p.r, ch = h - p.t - p.b;
  const max = niceMax(Math.max(...values)), ticks = 4;
  let b = '';
  for (let i = 0; i <= ticks; i++) {
    const y = p.t + ch - ch * i / ticks;
    b += `<line x1="${p.l}" y1="${y}" x2="${w - p.r}" y2="${y}" stroke="${GRID}"/>`;
    b += `<text x="${p.l - 8}" y="${y + 4}" text-anchor="end" fill="${MUTED}" font-size="11">${fmtAxis(max * i / ticks)}</text>`;
  }
  const pts = values.map((v, i) => [p.l + (labels.length === 1 ? cw / 2 : cw * i / (labels.length - 1)), p.t + ch - (v / max) * ch]);
  let d = `M ${pts[0][0]} ${pts[0][1]}`;
  for (let i = 1; i < pts.length; i++) {
    const mx = (pts[i - 1][0] + pts[i][0]) / 2;
    d += ` C ${mx} ${pts[i - 1][1]}, ${mx} ${pts[i][1]}, ${pts[i][0]} ${pts[i][1]}`;
  }
  b += `<path d="${d}" fill="none" stroke="${AMBER}" stroke-width="2.5" stroke-linecap="round"/>`;
  pts.forEach(([x, y], i) => {
    const dim = ativos.size && !ativos.has(labels[i]) ? 0.35 : 1;
    b += `<text x="${x}" y="${y - 10}" text-anchor="middle" fill="#fff" font-size="11" font-weight="600" opacity="${dim}">${fmtLabel(values[i])}</text>`;
    b += `<circle class="hit" data-filtro="fMes" data-valor="${esc(labels[i])}" cx="${x}" cy="${y}" r="5" fill="${AMBER}" stroke="#2b2b2b" stroke-width="1.5" opacity="${dim}"><title>${esc(nomeMes(labels[i]))}: ${esc(fmtBRL(values[i]))}</title></circle>`;
    b += `<text x="${x}" y="${h - 10}" text-anchor="middle" fill="${MUTED}" font-size="11">${nomeMes(labels[i])}</text>`;
  });
  setChart('chartMensal', svg(w, h, b, 'Faturamento por mês'));
}

function renderBarrasH(id, entries, filtroId, ativos, titulo, fmt = fmtLabel) {
  if (!entries.length) return setChart(id, empty());
  const w = 520, h = 280, p = { l: 128, r: 70, t: 10, b: 10 };
  const cw = w - p.l - p.r, rowH = (h - p.t - p.b) / entries.length, max = Math.max(...entries.map(e => e[1])) || 1;
  let b = '';
  entries.forEach(([nome, val], i) => {
    const bh = rowH * 0.58, y = p.t + i * rowH + (rowH - bh) / 2, bw = Math.max(2, (val / max) * cw);
    const dim = filtroId && ativos.size && !ativos.has(nome) ? 0.35 : 1;
    const curto = nome.length > 20 ? nome.slice(0, 19) + '…' : nome;
    b += `<text x="${p.l - 8}" y="${y + bh * 0.72}" text-anchor="end" fill="${TXT}" font-size="11">${esc(curto)}</text>`;
    b += `<rect ${filtroId ? `class="hit" data-filtro="${filtroId}" data-valor="${esc(nome)}"` : ''} x="${p.l}" y="${y}" width="${bw}" height="${bh}" fill="${AMBER}" opacity="${dim}"><title>${esc(nome)}: ${esc(fmt === fmtLabel ? fmtBRL(val) : fmtNum(val))}</title></rect>`;
    b += `<text x="${p.l + bw + 6}" y="${y + bh * 0.72}" fill="#fff" font-size="11" font-weight="600">${fmt(val)}</text>`;
  });
  setChart(id, svg(w, h, b, titulo));
}

// ---------- Insights (calculados sobre os dados filtrados) ----------
function gerarInsight(total, catEntries, meses, porMes, filtrando) {
  const partes = [];
  if (total > 0 && catEntries.length) {
    const [nome, val] = catEntries[0], pct = val / total * 100;
    partes.push(catEntries.length === 1 ? `${nome} responde por 100% do faturamento` : `${nome} ≈ ${Math.round(pct)}% do Faturamento`);
  }
  let pior = null;
  for (let i = 1; i < meses.length; i++) {
    const a = porMes[meses[i - 1]], c = porMes[meses[i]];
    if (a > 0) { const v = (c - a) / a; if (v < 0 && (!pior || v < pior.v)) pior = { i, v }; }
  }
  if (pior) {
    const m = nomeMes(meses[pior.i]), a = pior.i + 1 < meses.length ? meses[pior.i + 1] : null;
    let t = `Queda em ${m} (${dec(pior.v * 100, 1)}%)`;
    if (a && porMes[a] > porMes[meses[pior.i]]) t += `, Recuperação em ${nomeMes(a)}`;
    partes.push(t);
  }
  return partes.length ? partes.join(' e ') : 'Sem dados para os filtros selecionados.';
}

// ---------- Render ----------
function render() {
  const sR = selecionados('fRegiao'), sC = selecionados('fCategoria'), sM = selecionados('fMes');
  const f = VENDAS.filter(r => (!sR.size || sR.has(r.regiao)) && (!sC.size || sC.has(r.categoria)) && (!sM.size || sM.has(r.mes)));
  const soma = (arr, k) => arr.reduce((s, r) => s + Number(r[k] || 0), 0);
  const fat = soma(f, 'faturamento'), ped = new Set(f.map(r => r.id_pedido)).size, uni = soma(f, 'quantidade');
  const tk = ped ? fat / ped : 0;

  const setKpi = (id, txt, exato) => { const el = document.getElementById(id); el.textContent = txt; el.title = exato; };
  setKpi('kFaturamento', fmtPBI(fat), fmtBRL(fat));
  setKpi('kPedidos', fmtNum(ped), `${fmtNum(ped)} pedidos`);
  setKpi('kTicket', fmtPBI(tk), fmtBRL(tk));
  setKpi('kUnidades', fmtNum(uni), `${fmtNum(uni)} unidades`);

  const agrupar = k => { const o = {}; f.forEach(r => o[r[k]] = (o[r[k]] || 0) + Number(r.faturamento || 0)); return Object.entries(o).sort((a, b) => b[1] - a[1]); };
  const cat = agrupar('categoria'), reg = agrupar('regiao'), ven = agrupar('vendedor');
  const porMes = Object.fromEntries(meses.map(m => [m, 0]));
  f.forEach(r => porMes[r.mes] += Number(r.faturamento || 0));

  renderCategoria(cat, sC);
  renderMensal(meses, meses.map(m => porMes[m]), sM);
  const prodTodos = agrupar('produto');
  const pedProd = {};
  const setsProd = {};
  f.forEach(r => (setsProd[r.produto] ||= new Set()).add(r.id_pedido));
  Object.entries(setsProd).forEach(([k, v]) => pedProd[k] = v.size);
  renderBarrasH('chartPedidosProduto', Object.entries(pedProd).sort((a, b) => b[1] - a[1]), null, null, 'Pedidos por produto', fmtNum);
  renderBarrasH('chartProdutos', prodTodos, null, null, 'Faturamento por produto');
  const catProd = Object.fromEntries(VENDAS.map(r => [r.produto, r.categoria]));
  const uniProd = {};
  f.forEach(r => uniProd[r.produto] = (uniProd[r.produto] || 0) + Number(r.quantidade || 0));
  document.querySelector('#tblProdutos tbody').innerHTML = prodTodos.length
    ? prodTodos.map(([n, v]) => `<tr><td>${esc(n)}</td><td>${esc(catProd[n])}</td><td>${fmtBRL(v)}</td><td>${fmtNum(uniProd[n])}</td></tr>`).join('')
    : `<tr><td colspan="4" style="text-align:center;color:${MUTED};padding:18px">Nenhum produto para os filtros selecionados.</td></tr>`;
  renderBarrasH('chartVendedor', ven, null, null, 'Faturamento por vendedor');
  renderBarrasH('chartRegiao', reg, 'fRegiao', sR, 'Faturamento por região');
  document.getElementById('insight').textContent = gerarInsight(fat, cat, sM.size ? [] : meses, porMes);

  const pv = {};
  f.forEach(r => { const v = pv[r.vendedor] ||= { fat: 0, ped: new Set() }; v.fat += Number(r.faturamento || 0); v.ped.add(r.id_pedido); });
  const linhas = Object.entries(pv).map(([nome, v]) => ({ nome, fat: v.fat, ped: v.ped.size, tk: v.fat / v.ped.size })).sort((a, b) => b.fat - a.fat);
  document.querySelector('#tblVendedores tbody').innerHTML = linhas.length
    ? linhas.map(v => `<tr><td>${esc(v.nome)}</td><td>${fmtNum(v.ped)}</td><td>${fmtBRL(v.fat)}</td><td>${fmtBRL(v.tk)}</td></tr>`).join('')
    : `<tr><td colspan="4" style="text-align:center;color:${MUTED};padding:18px">Nenhum vendedor para os filtros selecionados.</td></tr>`;
}

document.addEventListener('change', e => { if (e.target.matches('input[data-grupo]')) render(); });
document.addEventListener('click', e => {
  const alvo = e.target.closest('[data-filtro]');
  if (alvo) toggleFiltro(alvo.dataset.filtro, alvo.dataset.valor);
});
document.getElementById('fReset').addEventListener('click', () => {
  document.querySelectorAll('input[data-grupo]').forEach(i => i.checked = false);
  render();
});
const abas = [...document.querySelectorAll('.tabs [role="tab"]')];
function abrirAba(n, foco) {
  abas.forEach((a, i) => {
    const on = i === n;
    a.setAttribute('aria-selected', String(on));
    a.tabIndex = on ? 0 : -1;
    document.getElementById(`page-${i}`).hidden = !on;
    if (on && foco) a.focus();
  });
}
abas.forEach((a, i) => {
  a.addEventListener('click', () => abrirAba(i));
  a.addEventListener('keydown', e => {
    if (e.key === 'ArrowRight') abrirAba((i + 1) % abas.length, true);
    if (e.key === 'ArrowLeft') abrirAba((i - 1 + abas.length) % abas.length, true);
  });
});
render();
